from collections import deque

def minCost(n, edges, k):
    # Build the adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Can we reach node n-1 within k edges using only edges with weight <= money?
    def reachable(money):
        dist = [-1] * n
        dist[0] = 0
        queue = deque([0])
        while queue:
            u = queue.popleft()
            if u == n - 1:
                return True       # BFS depth is minimal and never exceeds k
            if dist[u] == k:
                continue          # cannot take any more edges from here
            for v, w in adj[u]:
                if w <= money and dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return False

    # Candidate answers are exactly the distinct edge weights
    weights = sorted(set(w for _, _, w in edges))

    # If repairing everything is not enough, it is impossible
    if not reachable(weights[-1]):
        return -1

    # Binary search for the smallest sufficient weight
    lo, hi = 0, len(weights) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if reachable(weights[mid]):
            hi = mid
        else:
            lo = mid + 1
    return weights[lo]
